import{esc}from './ui.js';
import{t,translateUi}from './i18n.js';
const KEY='salah-soft-depth-v1';
export function depthEnabled(){try{return localStorage.getItem(KEY)!=='off'}catch{return false}}
export function initSoftDepth(){document.documentElement.classList.toggle('soft-depth',depthEnabled())}
export function mountSoftDepthSetting(root){const groups=root.querySelector('.settings-grid');if(!groups||root.querySelector('#soft-depth'))return;const section=document.createElement('details');section.className='panel settings-group';section.innerHTML='<summary><span class="settings-label" data-i18n="softDepthUi.title">'+esc(t('softDepthUi.title'))+'</span></summary><div class="settings-group-body"><label class="switch-row" for="soft-depth"><span data-i18n="softDepthUi.enabled">'+esc(t('softDepthUi.enabled'))+'</span><input id="soft-depth" type="checkbox"></label><p class="muted" data-i18n="softDepthUi.note">'+esc(t('softDepthUi.note'))+'</p><p class="muted" id="soft-depth-status" role="status" hidden></p></div>';const atmosphere=[...groups.querySelectorAll('.settings-group')].find(group=>group.querySelector('[data-i18n="settings.appearance"]'));const body=atmosphere?.querySelector('.settings-group-body');if(body){const content=section.querySelector('.settings-group-body');body.prepend(...content.childNodes)}else groups.prepend(section);translateUi(root);const input=root.querySelector('#soft-depth');input.checked=depthEnabled();input.onchange=()=>{const before=depthEnabled();try{localStorage.setItem(KEY,input.checked?'on':'off');initSoftDepth()}catch{input.checked=before;const status=root.querySelector('#soft-depth-status');status.hidden=false;status.setAttribute('data-i18n','softDepthUi.saveFailed');status.textContent=t('softDepthUi.saveFailed')}}}
window.addEventListener('storage',event=>{if(event.key===KEY){initSoftDepth();const input=document.getElementById('soft-depth');if(input)input.checked=depthEnabled()}});
